import csv, re
from collections import Counter, defaultdict

def load_csv(path):
    with open(path, "r", encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))

train_rows = load_csv("data/train.csv")
val_rows = load_csv("data/validation.csv")

print("=== 1. Rozkład konkretnych znaczników [...] w linii Subject: ===")
tag_counts = defaultdict(lambda: {"train_spam": 0, "train_ham": 0, "val_spam": 0, "val_ham": 0})

for split_name, rows in [("train", train_rows), ("val", val_rows)]:
    for r in rows:
        subj_line = r["text"].splitlines()[0]
        tags = set(re.findall(r"\[[^\]]+\]", subj_line))
        for t in tags:
            key = f"{split_name}_{r[\x27label\x27]}"
            tag_counts[t][key] += 1

for t in sorted(tag_counts.keys(), key=lambda k: -(tag_counts[k]["train_spam"]+tag_counts[k]["train_ham"]+tag_counts[k]["val_spam"]+tag_counts[k]["val_ham"])):
    c = tag_counts[t]
    tot = sum(c.values())
    print(f"{t:42s} | train: spam={c[\x27train_spam\x27]:2d}, ham={c[\x27train_ham\x27]:2d} | val: spam={c[\x27val_spam\x27]:2d}, ham={c[\x27val_ham\x27]:2d} | total={tot:2d}")

